/* AI prompt table (2026-11-06). One row only (Id = 1). Edit screen: /QuizAiPrompt/Index
   Run once before publishing. Running again keeps the table and any edited text.
   The text is stored as hex so the file has no Korean letters and no BOM.
   Expected result: PromptLength = 2862 */
SET NOCOUNT ON;

IF OBJECT_ID(N'dbo.QuizAiPrompt', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.QuizAiPrompt
    (
        Id         int            NOT NULL CONSTRAINT PK_QuizAiPrompt PRIMARY KEY CONSTRAINT CK_QuizAiPrompt_OneRow CHECK (Id = 1),
        PromptText nvarchar(max)  NOT NULL,
        UpdatedAt  datetime2(0)   NOT NULL,
        UpdatedBy  nvarchar(256)  NOT NULL
    );
END

IF NOT EXISTS (SELECT 1 FROM dbo.QuizAiPrompt WHERE Id = 1)
BEGIN
    INSERT INTO dbo.QuizAiPrompt (Id, PromptText, UpdatedAt, UpdatedBy)
    VALUES (1, CAST( AS nvarchar(max)), DATEADD(HOUR, 9, SYSUTCDATETIME()), N'basic');
END

SELECT Id, LEN(PromptText) AS PromptLength, UpdatedAt, UpdatedBy FROM dbo.QuizAiPrompt;
